function animate(env,el,p){
    function pad(s){ s=""+s; return s.length<2?"0"+s:s; }
    var t=env.absTime + p.offset*3600;
    var h=Math.floor(t/3600)%24, m=Math.floor(t/60)%60, s=Math.floor(t)%60;
    el.text = p.showHours ? pad(h)+":"+pad(m)+":"+pad(s) : pad(m)+":"+pad(s);
    return el;
}
